  "logiquest.explain": "Why?",
  "logiquest.q1": "If all roses are flowers, and all flowers need water, what follows?",
  "logiquest.q1.0": "All roses need water",
  "logiquest.q1.1": "Some roses need water",
  "logiquest.q1.2": "Roses don't need water",
  "logiquest.q1.3": "Can't determine",
  "logiquest.q1.correct": "0",
  "logiquest.q1.explain": "All A=B, all B=C → all A=C (transitive syllogism)",
  "logiquest.q2": "What comes next: 2, 4, 8, 16, ?",
  "logiquest.q2.0": "24",
  "logiquest.q2.1": "32",
  "logiquest.q2.2": "28",
  "logiquest.q2.3": "20",
  "logiquest.q2.correct": "1",
  "logiquest.q2.explain": "Each number doubles (×2): 16×2 = 32",
  "logiquest.q3": "🔴🟢🔵🔴🟢 — what's next?",
  "logiquest.q3.0": "🔴",
  "logiquest.q3.1": "🟢",
  "logiquest.q3.2": "🔵",
  "logiquest.q3.3": "🟡",
  "logiquest.q3.correct": "2",
  "logiquest.q3.explain": "Pattern repeats every 3: 🔴🟢🔵",
  "logiquest.q4": "What comes next: 1, 1, 2, 3, 5, 8, ?",
  "logiquest.q4.0": "11",
  "logiquest.q4.1": "12",
  "logiquest.q4.2": "13",
  "logiquest.q4.3": "14",
  "logiquest.q4.correct": "2",
  "logiquest.q4.explain": "Fibonacci: each number = sum of previous two (5+8=13)",
  "logiquest.q5": "A>B and B>C — who is smallest?",
  "logiquest.q5.0": "A",
  "logiquest.q5.1": "B",
  "logiquest.q5.2": "C",
  "logiquest.q5.3": "All equal",
  "logiquest.q5.correct": "2",
  "logiquest.q5.explain": "A > B > C, so C is the smallest",
  "logiquest.q6": "What is 15% of 200?",
  "logiquest.q6.0": "25",
  "logiquest.q6.1": "30",
  "logiquest.q6.2": "35",
  "logiquest.q6.3": "20",
  "logiquest.q6.correct": "1",
  "logiquest.q6.explain": "200 × 0.15 = 30",
  "logiquest.q7": "Which shape has the most sides?",
  "logiquest.q7.0": "Triangle",
  "logiquest.q7.1": "Square",
  "logiquest.q7.2": "Pentagon",
  "logiquest.q7.3": "Hexagon",
  "logiquest.q7.correct": "3",
  "logiquest.q7.explain": "Hexagon has 6 sides — the most of these four",
  "logiquest.q8": "ABCABC — what's the next letter?",
  "logiquest.q8.0": "A",
  "logiquest.q8.1": "B",
  "logiquest.q8.2": "C",
  "logiquest.q8.3": "D",
  "logiquest.q8.correct": "0",
  "logiquest.q8.explain": "The pattern ABC repeats → next is A",
  "logiquest.q9": "Today is Wednesday. What day is it 10 days from now?",
  "logiquest.q9.0": "Saturday",
  "logiquest.q9.1": "Sunday",
  "logiquest.q9.2": "Friday",
  "logiquest.q9.3": "Monday",
  "logiquest.q9.correct": "1",
  "logiquest.q9.explain": "Wed + 7 = Wed; Wed + 10 = Saturday… actually Wed+10 mod 7 = Wed+3 = Saturday? No: Wed(3)+10=13 mod 7=6=Sun",
  "logiquest.q10": "Complete: 3, 6, 12, 24, ?",
  "logiquest.q10.0": "36",
  "logiquest.q10.1": "42",
  "logiquest.q10.2": "48",
  "logiquest.q10.3": "30",
  "logiquest.q10.correct": "2",
  "logiquest.q10.explain": "Each number doubles (×2): 24×2 = 48",
  "logiquest.q11": "Odd one out: Dog, Cat, Rose, Bird",
  "logiquest.q11.0": "Dog",
  "logiquest.q11.1": "Cat",
  "logiquest.q11.2": "Rose",
  "logiquest.q11.3": "Bird",
  "logiquest.q11.correct": "2",
  "logiquest.q11.explain": "Rose is a plant; the others are animals",
  "logiquest.q12": "All birds fly. Penguins are birds. What is true?",
  "logiquest.q12.0": "Penguins fly",
  "logiquest.q12.1": "Penguins don't fly",
  "logiquest.q12.2": "The premise has an error",
  "logiquest.q12.3": "Cannot determine",
  "logiquest.q12.correct": "2",
  "logiquest.q12.explain": "The first premise is false — not all birds fly",
  "logiquest.q13": "If APPLE costs $50 and ORANGE $60, what does GRAPE cost? (letters × $10)",
