  "logiquest.q13.1": "$50",
  "logiquest.q13.2": "$50",
  "logiquest.q13.3": "$55",
  "logiquest.q13.correct": "0",
  "logiquest.q13.explain": "GRAPE = 5 letters × $10 = $50",
  "logiquest.q14": "Mary is older than John. John is older than Sam. Who is youngest?",
  "logiquest.q14.0": "Mary",
  "logiquest.q14.1": "John",
  "logiquest.q14.2": "Sam",
  "logiquest.q14.3": "Cannot tell",
  "logiquest.q14.correct": "2",
  "logiquest.q14.explain": "Mary > John > Sam, so Sam is youngest",
