  "logiquest.q17.1": "🌑",
  "logiquest.q17.2": "🌒",
  "logiquest.q17.3": "🌓",
  "logiquest.q17.correct": "1",
  "logiquest.q17.explain": "Moon phases: Full→Waning Gibbous→Half→Crescent→New Moon 🌑",
  "logiquest.q18": "Complete: 100, 50, 25, 12.5, ?",
