  "logiquest.q18.3": "7",
  "logiquest.q18.correct": "2",
  "logiquest.q18.explain": "Each number halves (÷2): 12.5÷2 = 6.25",
  "logiquest.q19": "Which is heaviest: 1kg iron, 1kg cotton, 1kg feathers?",
