  "jungle.howTo.1": "You are stranded in the jungle — make survival choices",
  "jungle.howTo.2": "Each choice affects your HP and score differently",
  "jungle.howTo.3": "If your HP reaches 0, the game ends",
  "jungle.howTo.4": "Survive all 8 scenarios to win!",
  "jungle.scene6": "You find an injured bird. What do you do?",
  "jungle.s6c1": "Carefully carry it — it might lead you to a path (+5 HP, +25 pts)",
  "jungle.s6c2": "Leave it — caring for it wastes energy (0 HP, +10 pts)",
  "jungle.scene7": "A river blocks your path. The water looks fast.",
  "jungle.s7c1": "Build a raft from fallen logs (−5 HP, +40 pts)",
  "jungle.s7c2": "Walk upstream to find a shallow crossing (+10 HP, +20 pts)",
  "jungle.scene8": "You see smoke in the distance.",
  "jungle.s8c1": "Head toward the smoke — could be rescue! (+15 HP, +45 pts)",
  "jungle.s8c2": "Avoid it — could be a wildfire (−5 HP, +15 pts)",
  "jungle.scene9": "Night falls. You need shelter.",
  "jungle.s9c1": "Climb a tall tree to stay safe from predators (+10 HP, +30 pts)",
  "jungle.s9c2": "Build a ground shelter with branches (−5 HP, +35 pts)",
  "jungle.scene10": "You find a fruit you don't recognize. You're very hungry.",
  "jungle.s10c1": "Eat it — you're starving! (−20 HP, +30 pts)",
  "jungle.s10c2": "Test a tiny piece on your skin first (0 HP, +20 pts)",
  "jungle.scene11": "A large snake coils on the path.",
  "jungle.s11c1": "Back away slowly and find a detour (+5 HP, +30 pts)",
  "jungle.s11c2": "Try to scare it away (−25 HP, +40 pts)",
  "jungle.scene12": "You hear a waterfall — your water supplies are critically low.",
  "jungle.s12c1": "Follow the sound to find fresh water (+20 HP, +35 pts)",
  "jungle.s12c2": "Ignore it and keep moving forward (−15 HP, +20 pts)",
  "jungle.scene13": "A storm is approaching rapidly.",
  "jungle.s13c1": "Find high ground and cover (+10 HP, +25 pts)",
  "jungle.s13c2": "Keep moving to escape it (−10 HP, +30 pts)",
  "jungle.scene14": "You find a cave. It's getting dark.",
  "jungle.s14c1": "Enter the cave for shelter (+15 HP, +30 pts)",
  "jungle.s14c2": "Sleep under a tree — the cave might be occupied (+5 HP, +20 pts)",
  "jungle.scene15": "You're exhausted. A clearing ahead looks safe.",
  "jungle.s15c1": "Rest and recover (+20 HP, +20 pts)",
  "jungle.s15c2": "Push on — rest is dangerous here (−5 HP, +30 pts)",
  "jungle.scene16": "You find an old map carved into a tree.",
  "jungle.s16c1": "Follow the map's direction (+5 HP, +40 pts)",
  "jungle.s16c2": "Ignore it — it might be outdated (0 HP, +10 pts)",
  "jungle.scene17": "Wild boars cross your path aggressively.",
  "jungle.s17c1": "Climb the nearest tree immediately (+5 HP, +30 pts)",
  "jungle.s17c2": "Stand your ground and shout (−20 HP, +35 pts)",
  "jungle.scene18": "You find an abandoned camp with supplies.",
  "jungle.s18c1": "Take everything useful (+20 HP, +50 pts)",
  "jungle.s18c2": "Leave it — someone might need it later (0 HP, +10 pts)",
  "jungle.scene19": "A monkey steals your food bag!",
  "jungle.s19c1": "Chase the monkey (−10 HP, +40 pts)",
  "jungle.s19c2": "Let it go — not worth the energy (+0 HP, +15 pts)",
  "jungle.scene20": "You hear a helicopter overhead.",
  "jungle.s20c1": "Light a signal fire immediately! (+30 HP, +60 pts)",
  "jungle.s20c2": "Wave your arms — it might see you (+5 HP, +40 pts)",
